			.modal-overlay {
			    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
			    background: rgba(10,14,26,0.85); display: flex; align-items: center; justify-content: center;
			    z-index: 10000; opacity: 0; pointer-events: none; transition: opacity 0.3s;
