			    resize: none; outline: none; margin-bottom: 16px;
			}
			.modal textarea:focus { border-color: var(--red); }
			.input-password {
			    width: 100%; padding: 10px; border-radius: 8px; border: 1px solid var(--border);
			    background: var(--bg-dark); color: var(--text-main); font-size: 14px; outline: none;
			    margin-bottom: 16px; text-align: center; letter-spacing: 2px;
			}
			.input-password:focus { border-color: var(--gold); }
			.modal-actions { display: flex; justify-content: flex-end; gap: 10px; }
			.modal-btn { padding: 8px 16px; border-radius: 6px; font-size: 12px; font-weight: 700; cursor: pointer; border: none; }
			.modal-btn.cancel { background: var(--bg-row-odd); color: var(--text-muted); border: 1px solid var(--border); }
			.modal-btn.confirm { background: var(--red-dim); color: var(--red); border: 1px solid var(--red); }

			tfoot td {
			    background: var(--bg-header); color: var(--gold); font-weight: 800;
			    padding: 10px 8px; border-top: 2px solid var(--gold); font-size: 12px;
			}

			@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
			tbody tr { animation: fadeIn 0.25s ease forwards; }
			</style>
			</head>
			<body>
			<div class='app'>
			    <div class='header'>
			        <div class='logo'>GS</div>
			        <div class='header-title'>Painel de Repasses</div>
			    </div>

			    <div class='summary'>
			        <div class='card'>
			            <div class='card-label'>Valor Total Repasses</div>
			            <div class='card-value'><span class='currency'>R$</span>" & FORMAT(vTotalValor, "#,##0.00") & "</div>
			            <div class='card-sub'>" & FORMAT(vCountRows, "0") & " clientes</div>
			        </div>
			        <div class='card'>
			            <div class='card-label'>Unidades</div>
			            <div class='card-value'>" & FORMAT(vCountUnidades, "0") & "</div>
			            <div class='card-sub'>unidades distintas</div>
			        </div>
			        <div class='card' id='card-approved'>
			            <div class='card-label'>Aprovados</div>
			            <div class='card-value' id='approved-count'>0 / " & FORMAT(vCountRows, "0") & "</div>
			            <div class='card-sub' id='approved-pct'>0% aprovado</div>
			        </div>
			    </div>

			    <div class='controls'>
			        <div class='search-box'>
			            <input type='text' id='search' placeholder='Buscar por CNPJ, nome ou unidade...' oninput='filterTable()'>
			        </div>
			        <div class='search-box' style='max-width:130px'>
			            <input type='date' id='search-date' onchange='filterTable()' title='Filtrar por Data'>
			        </div>
			        <button class='filter-btn active' onclick='setFilter(this,""all"")'>Todos</button>
			        <button class='filter-btn' onclick='setFilter(this,""approved"")'>Aprovados</button>
			        <button class='filter-btn' onclick='setFilter(this,""pending"")'>Pendentes</button>
			        <button class='filter-btn' onclick='setFilter(this,""rejected"")'>Reprovados</button>
			        <button class='btn-lock' id='btn-lock' onclick='toggleLock()'>🔒 Desbloquear</button>
			        <span class='count-badge' id='visible-count'></span>
			        <button class='btn-save' id='btn-copy' onclick='copyToExcel()' style='border-color:var(--gold); color:var(--gold); background:var(--gold-dim); margin-right:8px;'>Copiar</button>
			        <button class='btn-save' id='btn-save' onclick='gravarEstado()' style='display:none;'>Gravar</button>
			    </div>

			    <div class='table-wrap'>
			        <table>
			            <thead>
			                <tr>
			                    <th onclick='sortBy(""job"")'>JOB</th>
			                    <th onclick='sortBy(""dataCadastro"")'>Data Cadastro</th>
			                    <th onclick='sortBy(""nome"")'>Cliente</th>
			                    <th onclick='sortBy(""cnpj"")'>CNPJ</th>
			                    <th onclick='sortBy(""categoria"")'>Categoria</th>
			                    <th class='num' onclick='sortBy(""valor"")'>Valor</th>
			                    <th class='num' onclick='sortBy(""dataPagamento"")'>Data Pgto</th>
			                    <th>Unidade</th>
			                    <th>Nome Unidade</th>
			                    <th class='num' onclick='sortBy(""percUnidade"")'>% Repasse</th>
			                    <th class='num' onclick='sortBy(""percHonorario"")'>% JOB</th>
			                    <th class='num' onclick='sortBy(""valorUnit"")'>Vl. Repasse</th>
			                    <th class='num'>Status</th>
			                </tr>
			            </thead>
			            <tbody id='tbody'></tbody>
			            <tfoot id='tfoot'></tfoot>
			        </table>
			    </div>
			</div>
			<div class='modal-overlay' id='modal-reprova'>
			    <div class='modal'>
			        <div class='modal-title' id='modal-title'>Motivo da Reprovação</div>
			        <div id='motivo-leitura' style='display:none; font-size:13px; color:var(--text-main); margin-bottom:16px; background:var(--bg-dark); padding:12px; border-radius:8px; border:1px solid var(--border); min-height:80px;'></div>
			        <textarea id='motivo-texto' placeholder='Digite o motivo para reprovar este repasse...'></textarea>
			        <div class='modal-actions'>
			            <button class='modal-btn cancel' onclick='fecharModal()'>Fechar</button>
			            <button class='modal-btn confirm' id='btn-confirm-modal' onclick='confirmarReprova()'>Reprovar</button>
			        </div>
			    </div>
			</div>
			<div class='modal-overlay' id='modal-senha'>
			    <div class='modal' style='width: 300px; text-align:center;'>
			        <div class='modal-title' style='color:var(--gold);'>Acesso Restrito</div>
			        <div style='font-size:12px; color:var(--text-muted); margin-bottom:16px;'>Digite a senha para habilitar a edição</div>
			        <input type='password' id='senha-texto' class='input-password' placeholder='****'>
			        <div class='modal-actions' style='justify-content:center;'>
			            <button class='modal-btn cancel' onclick='fecharSenha()'>Cancelar</button>
			            <button class='modal-btn confirm' style='background:var(--gold-dim); color:var(--gold); border-color:var(--gold);' onclick='confirmarSenha()'>Desbloquear</button>
			        </div>
			    </div>
			</div>
			<div class='toast' id='toast'>Estado salvo com sucesso!</div>

			<script>
			var rawData = [" & vJsonRows & "];

			for (var i=0; i<rawData.length; i++) {
			    if (!rawData[i].status || rawData[i].status.trim() === '') {
			        rawData[i].status = 'Pendente';
			    }
			}

			var currentFilter = 'all';
			var currentSort = {key:'nome', asc:true};

			var hasUnsaved = false;
			var isUnlocked = false;

			function toggleLock() {
			    if (isUnlocked) {
			        isUnlocked = false;
			        document.getElementById('btn-lock').innerHTML = '🔒 Desbloquear';
			        document.getElementById('btn-lock').classList.remove('unlocked');
			        document.getElementById('btn-save').style.display = 'none';
			        renderTable();
			        return;
			    }
			    document.getElementById('senha-texto').value = '';
			    document.getElementById('modal-senha').classList.add('show');
			    document.getElementById('senha-texto').focus();
			}

			function fecharSenha() {
			    document.getElementById('modal-senha').classList.remove('show');
			}

			function confirmarSenha() {
			    var senha = document.getElementById('senha-texto').value;
			    if (senha === 'Gs@2026') {
			        isUnlocked = true;
			        document.getElementById('btn-lock').innerHTML = '🔓 Bloquear';
			        document.getElementById('btn-lock').classList.add('unlocked');
			        document.getElementById('btn-save').style.display = 'inline-block';
			        showToast('Edição liberada!');
			        fecharSenha();
			        renderTable();
			    } else {
			        showToast('Senha incorreta!');
			        document.getElementById('senha-texto').value = '';
			        document.getElementById('senha-texto').focus();
			    }
			}

			var API_URL = 'https://api-aprovacoes-94n5.onrender.com/api/aprovacoes';

			function loadSaved() {
			    fetch(API_URL, {method:'GET'})
			    .then(function(r){return r.json();})
			    .then(function(map){
			        if (map) {
			            for (var i=0;i<rawData.length;i++) {
			                var saved = map[String(rawData[i].id)];
			                if (saved !== undefined) {
			                    if (typeof saved === 'string') {
			                        rawData[i].status = saved;
			                    } else if (typeof saved === 'object') {
			                        rawData[i].status = saved.status;
			                        rawData[i].motivo = saved.motivo;
			                    }
			                } else if (!rawData[i].status || rawData[i].status === '') {
			                    rawData[i].status = 'Pendente';
			                }
			            }
			            renderTable();
			        }
			    })
			    .catch(function(e){ console.log('Servidor offline'); });
			}

			function fmtBRL(v) {
			    return 'R$ ' + Number(v).toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
			}

			var itemSendoReprovado = null;

			function setStatus(id, newStatus) {
			    if (!isUnlocked) {
			        showToast('Clique em 🔒 Desbloquear para editar!');
			        return;
			    }
			    var item = rawData.find(function(r){return r.id===id;});
			    if (!item) return;
			    if (newStatus === 'Reprovado') {
			        itemSendoReprovado = item;
			        document.getElementById('modal-title').textContent = 'Motivo da Reprovação';
			        document.getElementById('motivo-leitura').style.display = 'none';
			        document.getElementById('motivo-texto').style.display = 'block';
			        document.getElementById('motivo-texto').value = item.motivo || '';
			        document.getElementById('btn-confirm-modal').style.display = 'inline-block';
			        document.getElementById('modal-reprova').classList.add('show');
			        return;
			    }
			    item.status = newStatus;
			    item.motivo = '';
			    markUnsaved();
			}

			function lerMotivo(id) {
			    var item = rawData.find(function(r){return r.id===id;});
			    if (!item) return;
			    document.getElementById('modal-title').textContent = 'Motivo Registrado';
			    document.getElementById('motivo-texto').style.display = 'none';
			    document.getElementById('motivo-leitura').style.display = 'block';
			    document.getElementById('motivo-leitura').textContent = item.motivo || 'Nenhum motivo registrado.';
			    document.getElementById('btn-confirm-modal').style.display = 'none';
			    document.getElementById('modal-reprova').classList.add('show');
			}

			function fecharModal() {
			    document.getElementById('modal-reprova').classList.remove('show');
			    itemSendoReprovado = null;
			}

			function confirmarReprova() {
			    if (itemSendoReprovado) {
			        itemSendoReprovado.status = 'Reprovado';
			        itemSendoReprovado.motivo = document.getElementById('motivo-texto').value;
			        markUnsaved();
			    }
			    fecharModal();
			}

			function markUnsaved() {
			    hasUnsaved = true;
			    var btn = document.getElementById('btn-save');
			    btn.classList.add('has-changes');
			    btn.textContent = 'GRAVAR *';
			    renderTable();
			}

			function gravarEstado() {
			    var map = {};
			    for (var i=0;i<rawData.length;i++) {
			        map[String(rawData[i].id)] = {
			            status: rawData[i].status,
